/**
 * Writes scripts/data/qatar-obesity-glp1-market-research.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-qatar-obesity-glp1-cover.mjs.
 *
 *   node scripts/generate-qatar-obesity-glp1-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/qatar-obesity-glp1-market-research.json');

export const SARAH_CHEN_SANITY_ID = '498ba300-bfab-4a76-b256-b2139d4d66fe';

/** Every blogPost field that applies to a healthcare-silo article. */
export const QATAR_OBESITY_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-qatar-obesity-glp1-research.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.QATAR_OBESITY_GLP1_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.QATAR_OBESITY_GLP1_BODY_HTML.split('<h2')[0])
    .replace(/^Qatar obesity GLP-1 market research[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.QATAR_OBESITY_GLP1_META_TITLE,
      metaDescription: mod.QATAR_OBESITY_GLP1_META_DESCRIPTION,
      focusKeyword: 'Qatar obesity GLP-1 market research',
      keywords: [
        'Qatar obesity GLP-1 market research',
        'Wegovy Qatar',
        'oral GLP-1 Qatar',
        'Foundayo Qatar',
        'MOPH GLP-1 approval',
        'Hamad Medical Corporation Wegovy',
        'Qatar STEPS obesity',
        'Qatar market access',
      ],
      canonicalUrl: mod.QATAR_OBESITY_GLP1_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.QATAR_OBESITY_GLP1_META_TITLE,
      ogDescription: mod.QATAR_OBESITY_GLP1_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.QATAR_OBESITY_GLP1_COVER_IMAGE}`,
        alt: mod.QATAR_OBESITY_GLP1_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.QATAR_OBESITY_GLP1_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.QATAR_OBESITY_GLP1_SLUG },
    excerpt: mod.QATAR_OBESITY_GLP1_EXCERPT,
    publishedAt: mod.QATAR_OBESITY_GLP1_PUBLISHED_ISO,
    updatedAt: mod.QATAR_OBESITY_GLP1_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: SARAH_CHEN_SANITY_ID,
      name: 'Sarah Chen',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.QATAR_OBESITY_GLP1_HERO_IMAGE}`,
      alt: mod.QATAR_OBESITY_GLP1_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for Qatar obesity GLP-1 market research',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.QATAR_OBESITY_GLP1_TAGS],
    country: 'Qatar',
    language: 'en',
    readingTime: mod.QATAR_OBESITY_GLP1_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.QATAR_OBESITY_GLP1_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.QATAR_OBESITY_GLP1_EXECUTIVE_SUMMARY_HTML}\n\n${mod.QATAR_OBESITY_GLP1_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'Qatar GLP-1 sequence, 2024–2026',
        type: 'table',
        data: JSON.stringify(
          mod.QATAR_OBESITY_GLP1_SEQUENCE.map((event) => ({
            name: event.name,
            when: event.when,
            whatItMeans: event.whatItMeans,
          })),
        ),
        source: 'Aamal / Ebn Sina May 2025; Gulf Times; Lilly / ZAWYA September 2026',
      },
      portableText(
        firstParagraph ||
          'Qatar obesity GLP-1 market research is an access question, not a launch rumour.',
      ),
    ],
    faq: mod.QATAR_OBESITY_GLP1_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['who-does-obesity-market-research-saudi-arabia', 'obesity-market-research-kuwait'],
    ctaSection: { ...mod.QATAR_OBESITY_GLP1_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.QATAR_OBESITY_GLP1_BODY_HTML),
    factCheckedAt: mod.QATAR_OBESITY_GLP1_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/qatar-obesity-glp1-market-research-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of QATAR_OBESITY_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
